program_texts.cnt10_field0#0:
chaord 0.1
dialect core + molecular + carbon + research

system {
  cell 33.563 33.563 49.200
  pbc xyz
  state T 300.00
  assert dipole_p1 -0.213 +- 0.277 along z
  conserve atoms C 844 F 12 H 72 Li 2 O 39 P 2
}

physics {
  backend classical
}

crystal tube : cylinder axis z center 16.781 16.781 24.600 radius 6.781 A length 49.200 A {
  nanotube (10,10) length 49.200 A
}

liquid fluid : cylinder axis z center 16.781 16.781 24.600 radius 6.781 A length 49.200 A {
  molecules C3H4O3 8
  molecules C4H8O3 5
  molecules F6P 2
  molecules Li+ 2
  state density 0.357 g/cm3
  assert cn 0.0 +- 0.0 cutoff 3.10 A
  assert gr_peak 3.35 A height 6.98
}

residual none

provenance {
  dialects "core 0.1.0 + molecular 0.1.0 + carbon 0.2.0 + research 0.1.0"
  lift_version "0.1.0"
  note "composed tube-plus-liquid program (D35, docs/reviews/open_items_v4.md Y3): all-carbon three-coordinated components lifted through the chirality inference as crystal tube regions; atoms inside each cylinder as the confined fluid region; atoms outside as their own region"
  note "fluid density and g(r) referred to the tube-interior region volume (pipeline._fit_fluid_region's rule: a sub-region is not the box)"
  note "dipole P1 measured from the frame's own per-atom charges (n = 13 molecules, axis z); tol = 1/sqrt(n) = 0.277 is the a-priori standard-error bound of a mean of n cosines (Popoviciu, Mathematica (Cluj) 9, 129 (1935): variance <= 1 for a variable on [-1,1]), not an empirical floor"
}

